-- Generado por scripts/generar-manual-pantallas.mjs a partir de docs/manual-pantallas/*.txt. No editar a mano.
-- Sincroniza las fichas del manual de Aria con Supabase (proyecto ERP - Tideo). Idempotente.
BEGIN;
DELETE FROM public.asistente_manual_pasos WHERE ficha_clave IN ('caja','compras_gastos','inicio_operaciones','proceso_caja_chica','proceso_solpe_pago','tesoreria');
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
DO $verificacion$
BEGIN
  IF (SELECT count(*) FROM public.asistente_manual_fichas WHERE clave IN ('caja','compras_gastos','inicio_operaciones','proceso_caja_chica','proceso_solpe_pago','tesoreria')) <> 6 THEN
    RAISE EXCEPTION 'Sincronización del manual: se esperaban 6 fichas';
  END IF;
  IF (SELECT count(*) FROM public.asistente_manual_pasos WHERE ficha_clave IN ('caja','compras_gastos','inicio_operaciones','proceso_caja_chica','proceso_solpe_pago','tesoreria')) <> 36 THEN
    RAISE EXCEPTION 'Sincronización del manual: se esperaban 36 pasos';
  END IF;
END
$verificacion$;
COMMIT;
